head.script:
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 grid의 두번째 컬럼에 한글을 입력한다.
    //1. After running the sample, type Hangul in the second column of the grid.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'grid1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#G_grid1__column2').val('한글을')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 한글이 입력되어 진다.
    //1. Hangul is input.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_grid1__column2').val() == '한글을'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 입력상태에서 포커스를 아웃시킨다.
    //2. Turn the focus off in the input state.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 입력중인 한글이 사라진다(정상)
    //2. Hangul is disappearing (normal)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_0_1').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.insertRow();
    grid1.insertRow();
    grid1.insertRow();
    grid1.insertRow();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
